wgslVertex:
// Three.js r178 - Node System
struct VaryingsStruct {
	@location( 3 ) nodeVarying3 : vec2<f32>,
	@location( 4 ) nodeVarying4 : vec3<f32>,
	@location( 5 ) nodeVarying5 : vec4<f32>,
	@builtin( position ) Vertex : vec4<f32>
};
var<private> varyings : VaryingsStruct;
@vertex
fn main( @location( 0 ) uv : vec2<f32>, @location( 1 ) normal : vec3<f32>, @location( 2 ) color : vec4<f32>, @location( 3 ) position : vec3<f32> ) -> VaryingsStruct {
	varyings.nodeVarying3 = uv;
	varyings.nodeVarying4 = normal;
	varyings.nodeVarying5 = color;
	return varyings;
}

wgslFragment:
// Three.js r178 - Node System
// uniforms
struct objectStruct {
	light : vec4<f32>,
	chaos : vec4<f32>
};
@binding( 2 ) @group( 1 )
var<uniform> object : objectStruct;
// codes
fn helper( x : f32 ) -> f32 { return fract( x ); }
@fragment
fn main( @location( 3 ) nodeVarying3 : vec2<f32>,
	@location( 4 ) nodeVarying4 : vec3<f32>,
	@location( 5 ) nodeVarying5 : vec4<f32> ) -> OutputStruct {
	var normalLocal : vec3<f32>;
	var nodeVar0 : vec4<f32>;
	normalLocal = nodeVarying4;
	nodeVar0 = vec4<f32>( helper( object.chaos.x + nodeVarying3.x ), max( dot( normalize( normalLocal ), normalize( object.light.xyz ) ), 0.0 ), nodeVarying5.x, 1.0 );
	// result
	output.color = nodeVar0;
	return output;
}

glslVertex:
#version 300 es
// Three.js r178 - Node System
out vec2 nodeVarying3;
out vec3 nodeVarying4;
out vec4 nodeVarying5;
layout( location = 0 ) in vec2 uv;
layout( location = 1 ) in vec3 normal;
layout( location = 2 ) in vec4 color;
void main() {
	nodeVarying3 = uv;
	nodeVarying4 = normal;
	nodeVarying5 = color;
}

