	normalLocal = nodeVarying4;
	nodeVar0 = vec4( helper( f_chaos.x + nodeVarying3.x ), max( dot( normalize( normalLocal ), normalize( f_light.xyz ) ), 0.0 ), nodeVarying5.x, 1.0 );
